-- Generated by scripts/cloud_run.py sql from src/congestion/athena.py. Do not edit.
UNLOAD (
WITH raw AS (
    SELECT
        month,
        date_trunc('second', CAST(lpep_pickup_datetime AS timestamp))  AS pickup,
        date_trunc('second', CAST(lpep_dropoff_datetime AS timestamp)) AS dropoff,
        date_trunc('second', CAST(NULL AS timestamp))                  AS request,
        CAST(PULocationID AS integer)                                  AS pu_zone,
        CAST(DOLocationID AS integer)                                  AS do_zone,
        CAST(fare_amount AS double)                                    AS fare,
        CAST(coalesce(tip_amount, 0) AS double)                        AS tips,
        CAST(NULL AS double)                                           AS driver_pay,
        CAST(trip_distance AS double)                                  AS miles,
        CAST(coalesce(cbd_congestion_fee, 0) AS double)                AS fee,
        CAST(NULL AS boolean)                                          AS shared_req,
        CAST(NULL AS boolean)                                          AS shared_match
    FROM tlc.raw_green
), clean AS (
    SELECT *,
           date_diff('second', pickup, dropoff) / 6e1 AS minutes,
           CASE WHEN request IS NOT NULL AND date_diff('second', request, pickup) BETWEEN 0 AND 3600
                THEN date_diff('second', request, pickup) / 6e1 END AS wait_min
    FROM raw
    WHERE pickup >= date_parse(month, '%Y-%m') AND pickup < date_add('month', 1, date_parse(month, '%Y-%m'))
      AND date_diff('second', pickup, dropoff) BETWEEN 60 AND 4 * 3600
      AND miles >= 0 AND miles <= 100
      AND (fare IS NULL OR fare >= 0)
)
SELECT 'green' AS service, CAST(pickup AS date) AS date, pu_zone,
       count(*)                                          AS trips,
       count(*) FILTER (WHERE (CASE WHEN day_of_week(pickup) IN (6, 7) THEN hour(pickup) BETWEEN 9 AND 20 ELSE hour(pickup) BETWEEN 5 AND 20 END))                AS trips_peak,
       count(*) FILTER (WHERE do_zone IN (4, 12, 13, 45, 48, 50, 68, 79, 87, 88, 90, 100, 107, 113, 114, 125, 137, 144, 148, 158, 161, 162, 163, 164, 170, 186, 209, 211, 224, 229, 230, 231, 232, 233, 234, 246, 249, 261)) AS trips_to_cbd,
       count(*) FILTER (WHERE fee > 0)                   AS fee_trips,
       sum(fee)                                          AS fee_sum,
       sum(fare)                                         AS fare_sum,
       sum(tips)                                         AS tips_sum,
       sum(driver_pay)                                   AS driver_pay_sum,
       sum(miles)                                        AS miles_sum,
       sum(minutes)                                      AS minutes_sum,
       count(wait_min)                                   AS wait_trips,
       sum(wait_min)                                     AS wait_min_sum,
       count(*) FILTER (WHERE shared_req)                AS shared_requests,
       count(*) FILTER (WHERE shared_match)              AS shared_matches
FROM clean
WHERE pu_zone BETWEEN 1 AND 263
GROUP BY 1, 2, 3
)
TO 's3://<your-bucket>/out/zone_day/service=green/'
WITH (format = 'PARQUET', compression = 'SNAPPY');
